import { styleText } from "node:util";
import * as util from "util";
import { PassThrough } from "node:stream";

export function reportStyleText() {
const originalRed = util.inspect.colors.red;
util.inspect.colors.red = [33, 39];
console.log("color-cache-before", JSON.stringify(styleText("red", "x", {validateStream: false})));
util.inspect.colors.red = originalRed;
console.log("color-cache-after", JSON.stringify(styleText("red", "x", {validateStream: false})));
console.log("aliases", Object.keys(util.inspect.colors).includes("grey"), util.inspect.colors.grey === util.inspect.colors.gray);
const stored = styleText;
const formats = ["reset", "bold", "dim", "italic", "underline", "blink", "inverse", "hidden", "strikethrough", "doubleunderline", "black", "red", "green", "yellow", "blue", "magenta", "cyan", "white", "bgBlack", "bgRed", "bgGreen", "bgYellow", "bgBlue", "bgMagenta", "bgCyan", "bgWhite", "framed", "overlined", "gray", "redBright", "greenBright", "yellowBright", "blueBright", "magentaBright", "cyanBright", "whiteBright", "bgGray", "bgRedBright", "bgGreenBright", "bgYellowBright", "bgBlueBright", "bgMagentaBright", "bgCyanBright", "bgWhiteBright", "grey", "blackBright", "bgGrey", "bgBlackBright", "faint", "crossedout", "strikeThrough", "crossedOut", "conceal", "swapColors", "swapcolors", "doubleUnderline", "none"];
for (const format of formats) {
  for (const text of ["", "café 😀", "first\nsecond", "a\u001b[39mb", "a\u001b[22mb", "a\u001b[24mb", "a\u001b[0mb", "a\u001b[39m", "embedded\u0000end"]) {
    console.log(format, JSON.stringify(styleText(format, text, { validateStream: false })));
  }
}
for (const format of [[], ["none"], ["bold", "green"], ["red", "green"], ["dim", "bold", "dim"], ["none", "underline", "italic"], ["reset", "red"]]) {
  console.log("array", JSON.stringify(stored(format, "before\u001b[39mmiddle\u001b[22mafter", { validateStream: false })));
}
console.log("identity", styleText === stored, styleText === util.styleText);
console.log("nested", JSON.stringify(styleText("red", styleText("blue", "nested", { validateStream: false }) + " tail", { validateStream: false })));
console.log("default", JSON.stringify(styleText("none", "plain")));
const style = styleText;
for (const value of [undefined, null, false, 0, -0, NaN, Infinity, 2n, Symbol("x"), {}, [1, 2]]) {
  try { console.log("text", style("red", value, { validateStream: false })); }
  catch (error) { console.log(error.name, error.code, error.message); }
  try { console.log("format", style(value, "x", { validateStream: false })); }
  catch (error) { console.log(error.name, error.code, error.message); }
  try { console.log("options", style("red", "x", value)); }
  catch (error) { console.log(error.name, error.code, error.message); }
  try { console.log("flag", style(["red"], "x", { validateStream: value })); }
  catch (error) { console.log(error.name, error.code, error.message); }
}
for (const name of ["bad", "toString", "constructor", "__proto__", "a\nb", "a'b", 'a"b', "a'b\"c"]) {
  try { style(name, "x", { validateStream: false }); }
  catch (error) { console.log("bad-style", error.name, error.code, error.message); }
}
for (const options of [null, [], 2, "x", {validateStream: 0}, {validateStream: ""}, {validateStream: null}, {validateStream: false, stream: 2}, {stream: 2}, {stream: {}}, {stream: {isTTY: true}}]) {
  try { console.log("fast", JSON.stringify(stored("red", "x", options))); }
  catch (error) { console.log("fast", error.name, error.code, error.message); }
}
try { style(); } catch (error) { console.log("missing", error.name, error.code, error.message); }
try { stored("red"); } catch (error) { console.log("missing-stored", error.name, error.code, error.message); }
let order = "";
function input(value) { order += value; return value; }
function extra() { order += "extra"; return null; }
console.log("order", JSON.stringify(style(input("red"), input("text"), {validateStream: false}, extra())), order);
try { style("bad", "x", {validateStream: false}, extra()); }
catch (error) { console.log("order-error", order, error.code); }
const mutableFormats = ["red"];
function mutate() { mutableFormats[0] = "green"; return null; }
console.log("live", JSON.stringify(style(mutableFormats, "x", {validateStream: false}, mutate())));

const options = { get validateStream() { console.log("get-flag"); return false; }, get stream() { throw new Error("unused stream"); } };
console.log("getter", JSON.stringify(styleText("red", "x", options)));
const inherited = Object.create({validateStream: false});
console.log("inherited", JSON.stringify(styleText(["bold", "green"], "x", inherited)));
const converted = { toString() { console.log("format-toString"); return "red"; } };
console.log("converted", JSON.stringify(styleText([converted], "x", {validateStream: false})));
const sparse = []; sparse.length = 1;
try { styleText(sparse, "x", {validateStream: false}); } catch (error) { console.log("sparse", error.name, error.code, error.message); }
const stream = new PassThrough();
console.log("custom-stream", JSON.stringify(styleText("red", "x", {stream})));
stream.isTTY = true;
stream.getColorDepth = () => 1;
console.log("depth-one", JSON.stringify(styleText("red", "x", {stream})));
stream.getColorDepth = () => 4;
console.log("depth-four", JSON.stringify(styleText("red", "x", {stream})));
stream.destroy();
const webReadable = new ReadableStream({start(controller) {controller.close();}});
console.log("web-stream", JSON.stringify(styleText("red", "x", {stream: webReadable})));
console.log("ignored-stream", JSON.stringify(styleText("red", "x", {validateStream: false, stream: Symbol("unused")})));
const originalForce = process.env.FORCE_COLOR;
const originalNoColor = process.env.NO_COLOR;
const originalDisable = process.env.NODE_DISABLE_COLORS;
delete process.env.FORCE_COLOR;
delete process.env.NO_COLOR;
delete process.env.NODE_DISABLE_COLORS;
for (const force of ["", "0", "1", "2", "3", "true", "false", "4", "01", "blue"]) {
  process.env.FORCE_COLOR = String(force);
  console.log("force " + force + " " + JSON.stringify(styleText(["bold", "red"], "x")));
  console.log("stderr " + force + " " + JSON.stringify(styleText("green", "x", {stream: process.stderr})));
  console.log("bypass " + force + " " + JSON.stringify(styleText("blue", "x", {validateStream: false})));
}
delete process.env.FORCE_COLOR;
for (const disabled of ["", "1"]) {
  process.env.NO_COLOR = String(disabled);
  console.log("no-color " + disabled + " " + JSON.stringify(styleText("red", "x")));
  console.log("explicit " + disabled + " " + JSON.stringify(styleText("red", "x", {validateStream: false})));
  delete process.env.NO_COLOR;
  process.env.NODE_DISABLE_COLORS = String(disabled);
  console.log("disabled " + disabled + " " + JSON.stringify(styleText("green", "x", {stream: process.stdout})));
  delete process.env.NODE_DISABLE_COLORS;
}
if (originalForce === undefined) delete process.env.FORCE_COLOR; else process.env.FORCE_COLOR = String(originalForce);
if (originalNoColor === undefined) delete process.env.NO_COLOR; else process.env.NO_COLOR = String(originalNoColor);
if (originalDisable === undefined) delete process.env.NODE_DISABLE_COLORS; else process.env.NODE_DISABLE_COLORS = String(originalDisable);
}
